// Private Telegram article/link intake. No sender ID authorization; /commands are ignored.
const rows=$input.all();
if(rows.length!==1)throw new Error('Telegram intake: expected one update');
const msg=rows[0]?.json?.message;
if(!msg||msg.chat?.type!=='private'||msg.chat?.id==null||!Number.isSafeInteger(msg.message_id))return [];
const chat_id=String(msg.chat.id);
const value=(typeof msg.text==='string'?msg.text:typeof msg.caption==='string'?msg.caption:'').trim();
if(!value||value.startsWith('/')||value.length>12000)return [];
// n8n Code sandbox does not expose the URL constructor; parse a strict public HTTPS hostname instead.
const urls=[],safeUrl=s=>{
 if(typeof s!=='string'||!/^https:\/\/[^\s/?#]+(?:[/?#][^\s]*)?$/i.test(s))return null;
 const host=(s.match(/^https:\/\/([^/?#]+)/i)||[])[1]?.toLowerCase().replace(/\.$/,'')||'';
 if(!/^(?:[a-z0-9-]+\.)+[a-z]{2,}$/i.test(host)
    ||/(^|\.)(localhost|local|internal|test|invalid|onion|lan|home|corp)$/.test(host))return null;
 return s;
};
for(const m of value.matchAll(/https?:\/\/[^\s<>"')\]]+/g)){
 const u=safeUrl(m[0].replace(/[.,!?;:，。！？；：]+$/g,''));
 if(u&&!urls.includes(u))urls.push(u);
 if(urls.length===3)break;
}
for(const e of [...(msg.entities||[]),...(msg.caption_entities||[])]){
 if(e?.type==='text_link'&&typeof e.url==='string'&&urls.length<3){
  const u=safeUrl(e.url);if(u&&!urls.includes(u))urls.push(u);
 }
}
const other=value.replace(/https?:\/\/[^\s<>"')\]]+/g,'').trim();
const article=other.length>=160?value:null;
if(!urls.length&&!article)return [];
const lines=other.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);
const first=lines.find(s=>!/^请(?:写|研究|处理)/.test(s))||'';
let title=first.length>=8&&first.length<=160?first:'';
if(!title&&urls.length){
 const url=urls[0],host=(url.match(/^https:\/\/([^/?#]+)/i)||[])[1]||'';
 const path=url.replace(/^https:\/\/[^/?#]+/i,'').split(/[?#]/)[0];
 const slug=path.split('/').filter(Boolean).at(-1)||host;
 try{title=(decodeURIComponent(slug).replace(/[-_]+/g,' ').replace(/\.(html?|php)$/i,'')+' '+host).trim().slice(0,160);}catch{title=host;}
}
if(!title&&article)title=lines[0]?.slice(0,140)||'Telegram article';
if(!title)return [];
const materials=article?[{source:'telegram_submission',url:null,title,retrieval:{phase:'initial',method:'telegram_user_input',status:'user_supplied_unverified',raw_content:article,retrieved_at:new Date().toISOString()}}]:[];
return [{json:{stage:'initial_research',content_id:'telegram:'+chat_id+':'+msg.message_id,title,
 human_instructions:'',
 selected_topic:{selection_value:1,status:'selected',title,source_urls:urls},
 target_urls:urls,materials,source_links:[],image_candidates:[],
 telegram_submission:{chat_id,message_id:msg.message_id,kind:article?'article_text':'url',urls},
 publication:{state:'NOT_PUBLISHED',url:null}},pairedItem:{item:0}}];

// Add retrieval targets to the selected context. Fixed services do not need an LLM router.
// Existing daily approval OR authorized Telegram submission.
let c;
try { c=$('Parse Selection1').first().json; } catch(e) {}
if(!c) c=$('Telegram Submission Intake').first().json;
const search=$input.first().json;
const text=v=>typeof v==='string'&&v.trim().length>0;
const valid=u=>typeof u==='string'&&/^https?:\/\/[^\s]+$/i.test(u);
const key=u=>u.replace(/#.*$/,'').replace(/\/$/,'');
if(c?.stage!=='initial_research'||!text(c.title)||!Array.isArray(c.materials)
 ||!Array.isArray(c.target_urls)||(!c.target_urls.length&&!c.materials.some(m=>typeof m?.retrieval?.raw_content==='string'&&m.retrieval.raw_content.trim()))||!c.target_urls.every(valid)
 ||typeof c.human_instructions!=='string')throw new Error('Initial research: selected topic and original URLs required');
// shortcut: Telegram still runs the existing search; skip its results until request-count optimization is needed.
const found=Array.isArray(search.web?.results)?search.web.results:[];
const selected=[...c.target_urls,...(c.telegram_submission&&c.target_urls.length ? [] : found.map(x=>x.url))].filter(valid);
const targets=[...new Map(selected.map(u=>[key(u),u])).values()].slice(0,20);
const browser=u=>/^https?:\/\/(?:[^/]+\.)?(?:x\.com|twitter\.com|zhihu\.com|bloomberg\.com|wsj\.com|ft\.com|linkedin\.com)(?:[/:]|$)/i.test(u);
const urls=targets.filter(u=>!browser(u)), browser_urls=targets.filter(browser);
return [{json:{...c,initial_research:{
 search_query:c.title,search_results:found,search_error:search.error?(typeof search.error==='string'?search.error:JSON.stringify(search.error)):null,
 urls,browser_urls,requested_at:new Date().toISOString()
}},pairedItem:{item:0}}];

// Keep the returned source text, not a new LLM summary or per-claim dossier.
const c=$('Select Initial Sources').first().json, raw=$input.first().json;
const plan=c.initial_research;
const text=v=>typeof v==='string'&&v.trim().length>0;
const key=u=>typeof u==='string'?u.replace(/#.*$/,'').replace(/\/$/,''):'';
const error=v=>typeof v==='string'?v:JSON.stringify(v);
const usefulImage=u=>{
 if(typeof u!=='string'||!/^https?:\/\/[^\s]+$/i.test(u))return false;
 const path=u.toLowerCase().split(/[?#]/)[0];
 if(/\.(?:svg|ico)$/.test(path))return false;
 return !/(?:^|[\/_.-])(?:favicon|logo|icon|icons|avatar|sprite|emoji|badge|spacer|pixel|tracking|analytics)(?:[\/_.-]|$)/.test(path);
};
const results=Array.isArray(raw.results)?raw.results:[],failed=Array.isArray(raw.failed_results)?raw.failed_results:[];
const materials=c.materials.map(s=>({...s})), images=(c.image_candidates||[]).map(s=>({...s})), errors=[];
const links=(c.source_links||[]).map(s=>({...s}));
const fetched_at=new Date().toISOString();
// A Telegram-pasted article is material, not a verified source.
let body_count=materials.filter(s=>s?.retrieval?.method==='telegram_user_input'&&text(s.retrieval.raw_content)).length;
for(const url of plan.urls){
 const r=results.find(x=>key(x.url)===key(url)&&text(x.raw_content));
 const f=failed.find(x=>key(x.url)===key(url));
 const search=plan.search_results.find(x=>key(x.url)===key(url));
 let i=materials.findIndex(s=>key(s.origin_url||s.url)===key(url));
 if(i<0){i=materials.length;materials.push({source:'web_search',url,title:search?.title||r?.title||'',snippet:search?.description||'',published_at:search?.page_age||null});}
 const msg=r?null:error(f?.error||raw.error||'No non-empty source text returned');
 materials[i].retrieval={phase:'initial',method:'tavily_extract',url,status:r?'body_returned':'failed',raw_content:r?r.raw_content:'',error:msg,retrieved_at:fetched_at};
 if(!r){errors.push({url,error:msg});continue;}
 body_count++;
 if(c.target_urls.some(u=>key(u)===key(url))){
  for(const m of r.raw_content.matchAll(/(?<!!)\[([^\]\n]+)\]\(<?(https?:\/\/[^\s>)]+)>?(?:\s+"[^"]*")?\)/g)){
   if(m[1].startsWith('![')||links.some(x=>key(x.url)===key(m[2])&&x.source_url===url))continue;
   links.push({url:m[2],source_url:url,label:m[1]});
  }
 }
 const candidates=Array.isArray(r.images)?[...r.images]:[];
 for(const m of r.raw_content.matchAll(/!\[([^\]]*)\]\(<?(https?:\/\/[^\s>)]+)>?(?:\s+"[^"]*")?\)/g))candidates.push({url:m[2],alt_text:m[1]});
 for(const x of candidates){
  const image_url=typeof x==='string'?x:x?.url;
  if(!usefulImage(image_url))continue;
  const existing=images.find(v=>v.url===image_url&&v.source_url===url);
  if(existing){if(!existing.alt_text&&typeof x==='object'&&text(x.alt_text))existing.alt_text=x.alt_text;continue;}
  images.push({url:image_url,source_url:url,source_title:materials[i].title||'',alt_text:typeof x==='object'?x.alt_text||'':'',status:'unreviewed',kind:'source_image'});
 }
}
let title=c.title, selected_topic=c.selected_topic;
if(c.telegram_submission&&c.target_urls.length){
 const url=c.target_urls[0],host=(url.match(/^https:\/\/([^/?#]+)/i)||[])[1]||'';
 const path=url.replace(/^https:\/\/[^/?#]+/i,'').split(/[?#]/)[0];
 const slug=path.split('/').filter(Boolean).at(-1)||host;
 let placeholder;
 try{placeholder=(decodeURIComponent(slug).replace(/[-_]+/g,' ').replace(/\.(html?|php)$/i,'')+' '+host).trim().slice(0,160);}catch{placeholder=host;}
 const source=results.find(r=>key(r.url)===key(url)&&text(r.raw_content)&&text(r.title));
 if(title===placeholder&&source){
  title=source.title;
  if(selected_topic?.title===placeholder)selected_topic={...selected_topic,title};
 }
}
const status=body_count?(errors.length||plan.search_error||plan.browser_urls.length?'partial':'completed'):(plan.browser_urls.length?'browser_pending':'failed');
return [{json:{...c,title,selected_topic,materials,image_candidates:images,source_links:links,
 initial_research:{...plan,body_count,errors,status,completed_at:fetched_at},
 stage:body_count?'initial_research_ready':plan.browser_urls.length?'initial_research_browser_pending':'initial_research_failed',
 publication:{state:'NOT_PUBLISHED',url:null}
},pairedItem:{item:0}}];

