const prepared=$('Prepare Recent Bundle Reads').all(),base=prepared[0]?.json?.base||$('Visual Mode').first().json;
const errors=[...(prepared[0]?.json?.history_errors||[])],candidates=[],cache=new Map();
const publicUrl=u=>{if(typeof u!=='string'||u.length>2048||!/^https?:\/\/[^\s]+$/i.test(u))return false;const m=u.match(/^https?:\/\/((?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,})(?::(?:80|443))?(?:[/?#][^\s]*)?$/i);return !!m&&!/(^|\.)(?:localhost|local|internal|test|invalid|example|onion|lan|home|corp|private)$/i.test(m[1]);};
const testId=id=>/(^|[-_:])(?:test|temp|uat)(?:[-_:]|$)/i.test(id);
for(const [i,row] of $input.all().entries()){
 const raw=row.json||{},b=raw.bundle??raw.data??raw;
 if(raw.error){errors.push('recent_cover_bundle_read_failed');continue;}
 if(!b||typeof b!=='object'||Array.isArray(b)||typeof b.content_id!=='string')continue;
 const id=b.content_id;if(id===base.content_id||testId(id)||b.test_only===true||b.test?.only===true)continue;
 const pi=Array.isArray(row.pairedItem)?row.pairedItem[0]?.item:row.pairedItem?.item;
 const file=prepared.find(p=>p.json.file_id===b.persistence?.file_id)?.json||prepared[Number.isInteger(pi)?pi:i]?.json;
 if(!file?.has_history_file)continue;
 if(b.persistence?.file_id&&b.persistence.file_id!==file.file_id){errors.push('recent_cover_bundle_identity_mismatch');continue;}
 for(const ref of b.recent_cover_references||[])if(typeof ref?.content_id==='string'&&publicUrl(ref.url)&&ref.visual_read_status==='read'&&typeof ref.visual_description==='string'&&ref.visual_description.trim())cache.set(ref.content_id+'\n'+ref.url,ref.visual_description);
 let url=Object.values(b.illustrated_previews||{}).map(p=>p?.cover_image?.url).find(publicUrl);
 if(!url)url=(b.visuals?.assets||[]).filter(a=>a?.role==='cover'&&a.status!=='FAILED').map(a=>a?.asset?.url).find(publicUrl);
 if(!url)continue;
 candidates.push({content_id:id,title:b.title||Object.values(b.illustrated_previews||{}).find(p=>p?.article_title)?.article_title||'',url,file_id:file.file_id,modifiedTime:file.modifiedTime});
}
candidates.sort((a,b)=>Date.parse(b.modifiedTime)-Date.parse(a.modifiedTime)||a.file_id.localeCompare(b.file_id));
const seen=new Set(),references=[];
for(const ref of candidates){if(seen.has(ref.content_id))continue;seen.add(ref.content_id);const description=cache.get(ref.content_id+'\n'+ref.url);references.push({...ref,visual_read_status:description?'read':'not_read',...(description?{visual_description:description}:{})});if(references.length===3)break;}
const c={...base,recent_cover_references:references,recent_cover_history:{window_days:14,download_limit:6,status:references.length?'pending_read':errors.length?'unavailable':'empty',errors:[...new Set(errors)]}};
// Inspect source-linked images even when the page did not supply adjacent text.
const items=Array.isArray(c.image_candidates)?c.image_candidates:[],materials=Array.isArray(c.materials)?c.materials:[];
const articles=Object.values(c.previews||{}).map(p=>p?.article_markdown||'').join('\n');
const sourceFor=x=>materials.find(m=>[m.url,m.origin_url,m.retrieval?.url].includes(x.source_url)&&typeof m.retrieval?.raw_content==='string'&&m.retrieval.raw_content.trim());
const bodyImage=x=>!/(?:avatar|favicon|sprite|spinner|tracking|badge|\/tr\?|[-_]100x100\.|\/size\/w100\/)/i.test(x.url+' '+(x.alt_text||''));
const eligible=items.filter(x=>!(x?.visual_read_status==='read'&&typeof x.visual_description==='string'&&x.visual_description.trim())&&publicUrl(x?.url)&&publicUrl(x?.source_url)&&bodyImage(x)&&sourceFor(x));
const informative=x=>/(?:chart|benchmark|score|result|screenshot|图表|截图|评测|评分|价格|方案|\$\d)/i.test((x.image_context||'')+' '+(x.alt_text||''))||/(?:chart|benchmark|model-api|pbs\.twimg\.com\/media\/)/i.test(x.url);
const groups=new Map();
for(const x of eligible){const m=sourceFor(x);if(m.source!=='browser'&&m.retrieval?.phase!=='supplementary'&&![m.url,m.origin_url,m.retrieval?.url].some(u=>u&&articles.includes(u)))continue;const g=groups.get(x.source_url)||[];g.push(x);groups.set(x.source_url,g);}
for(const g of groups.values())g.sort((a,b)=>Number(informative(b))-Number(informative(a))||Number(!!b.alt_text)-Number(!!a.alt_text));
const queues=[...groups.values()].sort((a,b)=>Number(sourceFor(b[0]).source==='browser')-Number(sourceFor(a[0]).source==='browser')||Number(informative(b[0]))-Number(informative(a[0])));
const chosen=[],seenReads=new Set();
// Eight is a reading budget, not a required number of article images.
for(let round=0;chosen.length<8&&queues.some(g=>g.length>round);round++)for(const g of queues){const x=g[round];if(!x)continue;const k=x.url+'\n'+x.source_url;if(seenReads.has(k))continue;seenReads.add(k);chosen.push(x);if(chosen.length===8)break;}
const reads=chosen.map(x=>({json:{has_image_read:true,read_kind:'article_candidate',base:c,candidate_index:items.indexOf(x),candidate:x,recent_cover_indexes:[]},pairedItem:{item:0}}));
for(const [i,ref] of (c.recent_cover_references||[]).entries()){
 if(ref.visual_read_status==='read'&&typeof ref.visual_description==='string'&&ref.visual_description.trim())continue;
 if(!publicUrl(ref.url))continue;
 let item=reads.find(r=>r.json.candidate.url===ref.url);
 if(!item){item={json:{has_image_read:true,read_kind:'recent_cover',base:c,candidate_index:-1,candidate:{url:ref.url,source_title:ref.title,source_url:'',image_context:''},recent_cover_indexes:[]},pairedItem:{item:0}};reads.push(item);}
 item.json.recent_cover_indexes.push(i);
}
if(!reads.length)return [{json:{...c,has_image_read:false,base:c},pairedItem:{item:0}}];
return reads;

parameters.text:
=Describe the actual image in concise English (about 80–100 words).
For an article candidate, lead with the information a reader can see: chart axes, metric and billing units, model/version labels quoted exactly as written, and clearly readable values; an interface's action and result; a demonstration's visible output; or a person's visible words. Then briefly describe layout and legibility. Attribute only text actually visible in the image. If small text cannot be read, say which part is unclear.
For a recent cover, describe subject, composition, dominant colors, medium, texture and visible typography.
Page alt text and adjacent text are source context, not observations of the image. Describe; selection and placement belong to the visual editor.
Input role: {{ $json.read_kind || 'article_candidate' }}
Article: {{ $json.base?.previews?.['zh-CN']?.article_title || $json.base?.title || '' }}
Source: {{ $json.candidate.source_title }} ({{ $json.candidate.source_url }})
Page alt text: {{ $json.candidate.alt_text || '' }}
Page-adjacent text: {{ $json.candidate.image_context || '' }}
Source text for identifying names only, not a substitute for image observations: {{ ($json.base?.materials||[]).find(m=>[m.url,m.origin_url,m.retrieval?.url].includes($json.candidate.source_url))?.retrieval?.raw_content?.slice(0,4000) || '' }}
